def _restore_unbound_recreated_references(connection):
    """Repair old suffixes only when a deleted predecessor proves they are recreations."""
    records = connection.execute(sa.text('''
        SELECT a.id, a.shop_id, a.order_id, a.customer_reference, a.deleted_at,
               a.tracking_number, a.label_barcode, a.shipped_at, a.status, o.order_number
        FROM after_sales a JOIN orders o ON o.id = a.order_id ORDER BY a.id
    ''')).mappings().all()
    active = {(row['shop_id'], row['customer_reference']) for row in records if row['deleted_at'] is None}
    archived = {(row['shop_id'], row['order_id'], row['customer_reference'])
                for row in records if row['deleted_at'] is not None}
    audited = {row[0] for row in connection.execute(sa.text(
        'SELECT after_sale_id FROM cf_tracking_writebacks WHERE after_sale_id IS NOT NULL'))}
    sales = sa.table('after_sales', sa.column('id', sa.Integer), sa.column('customer_reference', sa.String),
                     sa.column('updated_at', sa.DateTime))
    purchases = sa.table('purchase_lists', sa.column('id', sa.Integer), sa.column('shop_id', sa.Integer),
        sa.column('after_sale_id', sa.Integer), sa.column('name', sa.String),
        sa.column('items', sa.JSON), sa.column('allocations', sa.JSON))
    for row in records:
        if row['deleted_at'] is not None or row['tracking_number'] or row['label_barcode'] or row['shipped_at'] or row['status'] == 'shipped' or row['id'] in audited:
            continue
        base = f"CF{str(row['order_number']).strip().removeprefix('#')}"
        old = row['customer_reference']
        suffix = old.removeprefix(base + '-') if old.startswith(base + '-') else ''
        if not suffix.isdigit() or int(suffix) < 2 or (row['shop_id'], base) in active:
            continue
        if (row['shop_id'], row['order_id'], base) not in archived:
            continue
        connection.execute(sales.update().where(sales.c.id == row['id']).values(
            customer_reference=base, updated_at=datetime.utcnow()))
        active.add((row['shop_id'], base))
        active.discard((row['shop_id'], old))
        # Update only display references linked to THIS live case. Quantities,
        # receipts, stock keys, allocations and deleted-case snapshots stay unchanged.
        linked = connection.execute(sa.select(purchases).where(purchases.c.shop_id == row['shop_id'])).mappings().all()
        for purchase in linked:
            keys = {line.get('group_key') for line in purchase['allocations'] or []
                    if str(line.get('after_sale_id') or '') == str(row['id'])}
            direct = purchase['after_sale_id'] == row['id']
            if not direct and not keys:
                continue
            items = []
            for item in purchase['items'] or []:
                item = dict(item)
                if direct or item.get('group_key') in keys:
                    item['order_numbers'] = [base if ref == old else ref for ref in item.get('order_numbers') or []]
                items.append(item)
            values = {'items': items}
            if direct and purchase['name'] == f'售后采购 {old}':
                values['name'] = f'售后采购 {base}'
            connection.execute(purchases.update().where(purchases.c.id == purchase['id']).values(**values))


